        rom[506] = {12'had8, 24'h9c4efe, 35'h70c0b86c8, 46'h3d001ef149a2, 57'h160053356d9fe60, 65'h1f7b746d25aa28cd9};
        rom[507] = {12'hadb, 24'h9c8533, 35'h70e7d2f2c, 46'h3d1546be2458, 57'h1607f48bb509829, 65'h1f917890cdd15b579};
